urn { enabled: section?.enabled !== false, providers: out }\n}\n\n/** The provider registry, compact enough for one settings page to hold. */\nfunction publicProviderRegistry() {\n  return listProviders().map(provider => ({\n    id: provider.id,\n    name: provider.name,\n    category: provider.category,\n    authKind: provider.auth?.kind ?? 'apiKey',\n    credentialUrl: provider.auth?.url ?? '',\n    baseUrl: provider.baseUrl ?? '',\n    baseUrlOverrideEnv: provider.baseUrlOverrideEnv ?? '',\n    format: provider.format,\n    website: provider.website ?? '',\n    notes: provider.notes ?? '',\n    local: provider.local === true,\n    modelCount: Array.isArray(provider.models) ? provider.models.length : 0,\n    models: (Array.isArray(provider.models) ? provider.models : []).map(model => ({\n      id: model.id,\n      name: model.name ?? model.id,\n      contextWindow: model.contextWindow ?? null,\n      vision: model.vision === true,\n      reasoning: model.reasoning === true,\n    })),\n  }))\n}\n\n/** The five local answers, in evaluation order. */\nconst OPTIMIZATION_KINDS = OPTIMIZATIONS\n\n/**\n * The local-optimization switches as the browser may see them.\n *\n * Each kind is reported individually even when the section is off, because the\n * page shows five separate switches: a master switch that silently blanked them\n * would look like the per-kind values had been lost.\n */\nfunction publicLocalOptimize(section) {\n  const config = section ?? {}\n  const out = { enabled: config.enabled !== false }\n  for (const kind of OPTIMIZATION_KINDS) out[kind] = config[kind] !== false\n  return out\n}\n\n/** The switches in the shape `tryOptimizations` wants. */\nfunction optimizeConfig(section) {\n  const publicView = publicLocalOptimize(section)\n  return publicView.enabled === true ? publicView : null\n}\n\n/**\n * Connection recipes for the local gateway.\n *\n * Generated rather than stored: the port can move when the requested one is\n * taken, so a snippet baked into the page at mount time is a snippet that lies\n * after a restart. Everything here is derived from what the listeners actually\n * bound and the keys they actually demand.\n */\nfunction clientSnippets({ forward, key, lanKey, models }) {\n  const running = forward.running === true\n  const base = running ? `http://127.0.0.1:${forward.port}` : 'http://127.0.0.1:<forward-port>'\n  const lanAddress = forward.lan.running === true && forward.lan.addresses.length > 0\n    ? `http://${forward.lan.addresses[0]}:${forward.lan.port}`\n    : ''\n  const shownKey = key === '' ? '<forward-key>' : key\n  const shownLanKey = lanKey === '' ? '<lan-key>' : lanKey\n  const sample = models[0] ?? 'deepseek-v4-flash-free'\n  const snippets = [\n    {\n      id: 'claude-code',\n      name: 'Claude Code',\n      language: 'bash',\n      body: [\n        `export ANTHROPIC_BASE_URL=${base}`,\n        `export ANTHROPIC_AUTH_TOKEN=${shownKey}`,\n        `export ANTHROPIC_MODEL=${sample}`,\n        '# the gateway speaks /v1/messages natively — no translation shim needed',\n      ].join('\\n'),\n    },\n    {\n      id: 'codex',\n      name: 'Codex CLI',\n      language: 'toml',\n      body: [\n        '# ~/.codex/config.toml',\n        'model_provider = \"ofm\"',\n        `model = \"${sample}\"`,\n        '',\n        '[model_providers.ofm]',\n        'name = \"Our Free Model\"',\n        `base_url = \"${base}/v1\"`,\n        'wire_api = \"responses\"',\n        `env_key = \"OFM_API_KEY\"`,\n      ].join('\\n'),\n    },\n    {\n      id: 'openai-sdk',\n      name: 'OpenAI SDK / any OpenAI-compatible tool',\n      language: 'python',\n      body: [\n        'from openai import OpenAI',\n        `client = OpenAI(base_url=\"${base}/v1\", api_key=\"${shownKey}\")`,\n        `client.chat.completions.create(model=\"${sample}\", messages=[{\"role\": \"user\", \"content\": \"hi\"}])`,\n      ].join('\\n'),\n    },\n    {\n      id: 'anthropic-sdk',\n      name: 'Anthropic SDK',\n      language: 'python',\n      body: [\n        'from anthropic import Anthropic',\n        `client = Anthropic(base_url=\"${base}\", api_key=\"${shownKey}\")`,\n        `client.messages.create(model=\"${sample}\", max_tokens=1024, messages=[{\"role\": \"user\", \"content\": \"hi\"}])`,\n      ].join('\\n'),\n    },\n    {\n      id: 'curl',\n      name: 'curl',\n      language: 'bash',\n      body: [\n        `curl ${base}/v1/chat/completions \\\\`,\n        `  -H \"authorization: Bearer ${shownKey}\" \\\\`,\n        '  -H \"content-type: application/json\" \\\\',\n        `  -d '{\"model\":\"${sample}\",\"messages\":[{\"role\":\"user\",\"content\":\"hi\"}]}'`,\n        '',\n        '# the Anthropic surface answers on the same port:',\n        `curl ${base}/v1/messages \\\\`,\n        `  -H \"x-api-key: ${shownKey}\" \\\\`,\n        '  -H \"anthropic-version: 2023-06-01\" \\\\',\n        '  -H \"content-type: application/json\" \\\\',\n        `  -d '{\"model\":\"${sample}\",\"max_tokens\":1024,\"messages\":[{\"role\":\"user\",\"content\":\"hi\"}]}'`,\n      ].join('\\n'),\n    },\n  ]\n  if (lanAddress !== '') {\n    snippets.push({\n      id: 'lan',\n      name: 'Another device on your network',\n      language: 'bash',\n      body: [\n        `# the LAN relay is up on this machine; its key is not the local one`,\n        `export OPENAI_BASE_URL=${lanAddress}/v1`,\n        `export OPENAI_API_KEY=${shownLanKey}`,\n      ].join('\\n'),\n    })\n  }\n  return {\n    running,\n    baseUrl: base,\n    lanUrl: lanAddress,\n    key: shownKey,\n    models,\n    snippets,\n  }\n}\n\nfunction publicCombo(entry) {\n  return {\n    id: entry.id, name: entry.name, models: entry.combo,\n    contextWindow: entry.contextWindow, maxOutput: entry.maxOutput, vision: entry.vision === true,\n  }\n}\n\nfunction publicSettings(settings, forwardInfo, egressInfo) {\n  return {\n    ...publicModelVisibility(settings),\n    enabled: settings.enabled !== false,\n    exposeRegionModels: settings.exposeRegionModels !== false,\n    probeIntervalMinutes: settings.probeIntervalMinutes ?? 15,\n    defaultMaxTokens: settings.defaultMaxTokens ?? 32768,\n    announcementAck: settings.announcementAck ?? '',\n    feedUrl: typeof settings.feedUrl === 'string' ? settings.feedUrl : '',\n    feedPollMinutes: settings.feedPollMinutes ?? 30,\n    notifyOs: settings.notifyOs === true,\n    updateCheckHours: settings.updateCheckHours ?? 6,\n    autoReloadWatch: settings.autoReloadWatch === true,\n    reloadedAt: settings.reloadedAt ?? 0,\n    reloadCount: settings.reloadCount ?? 0,\n    tokenSaver: publicTokenSaver(settings.tokenSaver),\n    aggregate: publicAggregate(settings.aggregate),\n    combos: normalizeCombos(settings.combos).map(combo => ({\n      id: combo.id,\n      name: combo.name,\n      models: combo.models,\n      strategy: combo.strategy,\n      stickyLimit: combo.stickyLimit,\n      enabled: combo.enabled,\n    })),\n    forward: {\n      ...(settings.forward ?? {}),\n      running: forwardInfo.running,\n      actualPort: forwardInfo.port,\n      error: forwardInfo.error,\n      notice: forwardInfo.notice ?? '',\n      lan: {\n        ...(settings.forward?.lan ?? {}),\n        running: forwardInfo.lan?.running === true,\n        actualPort: forwardInfo.lan?.port ?? 0,\n        host: forwardInfo.lan?.host ?? '',\n        error: forwardInfo.lan?.error ?? '',\n        addresses: forwardInfo.lan?.addresses ?? [],\n      },\n    },\n    // A subscription link is not an endpoint, it is a bearer credential: the\n    // path of the URL *is* the token, which is why it is handled like the\n    // forward keys and not like `feedUrl`. Stored as given, but never echoed —\n    // `urlLabel` is the masked host for the panel, `hasUrl` says whether one is\n    // set at all, and the value itself is served only by `GET /egress/url`, on\n    // the settings page's own ask (see src/egress.js `outletLabel`).\n    egress: {\n      ...pick(settings.egress ?? {}, ['enabled', 'mode', 'mihomoPath']),\n      hasUrl: String(settings.egress?.url ?? '') !== '',\n      urlLabel: outletLabel(settings.egress?.url ?? ''),\n      outlet: egressInfo?.outlet ?? '',\n      running: egressInfo?.running === true,\n      active: egressInfo?.active === true,\n      // The node url-test is carrying traffic on, its last measured delay, and\n      // how long reaching the gateway took. All three are readings, not state.\n      node: egressInfo?.node ?? '',\n      nodeDelayMs: egressInfo?.nodeDelayMs ?? 0,\n      latencyMs: egressInfo?.latencyMs ?? 0,\n      latencyAt: egressInfo?.latencyAt ?? 0,\n      error: egressInfo?.error ?? '',\n    },\n  }\n}\n\nfunction buildSummary(deps) {\n  const state = deps.state()\n  const snapshot = deps.availability.get()\n  const forwardInfo = deps.forwardInfo()\n  const update = deps.update.status()\n  const feedView = deps.announcements.view()\n  const defaultMaxTokens = deps.settings.get().defaultMaxTokens\n  // Lanes that carry no availability verdict of their own. The absorbed channels\n  // and the aggregate lane are named by a listing round that already succeeded,\n  // and a combo is a view over rows that were themselves named — none of them is\n  // pinged. A listing is not an inference verdict; explicit tests add their own samples.\n  const unprobed = entry => isEacEntry(entry) || isKiloEntry(entry) || isAggregateEntry(entry) || isComboEntry(entry) || isSubscriptionEntry(entry)\n  return {\n    catalog: state.catalog.map(entry => ({\n      ...entry,\n      hiddenByUser: isModelHidden(entry, state.settings),\n      hiddenByGroup: isModelHidden(entry, { ...state.settings, hiddenModelIds: [] }),\n      ...modelAvailability(entry.id, snapshot, unprobed(entry)),\n      // What each rung of the effort menu will really put on the wire for this\n      // model, so the page never shows a 32K \"output ceiling\" beside a call that\n      // was cut off at 8K. A model with no effort menu has no ladder to show;\n      // a menu model's rungs are flat (its level, not the ladder, is the wire\n      // control), which is what the card's \"default ceiling\" tag then reads.\n      ...(entry.reasoning === true ? { budgets: budgetLadder(entry, undefined, defaultMaxTokens) } : {}),\n      // `null` here is what the picker does not advertise; the roster still lists\n      // those models, because \"the probe refused it\" is the user's only evidence.\n      route: (state.membership[ROUTE_MAIN] ?? []).includes(entry.id) ? ROUTE_MAIN\n        : (state.membership[ROUTE_REGION] ?? []).includes(entry.id) ? ROUTE_REGION : null,\n    })),\n    settings: publicSettings(deps.settings.get(), forwardInfo, deps.egressInfo()),\n    egress: forwardInfo.egress ?? snapshot.egress ?? null,\n    outlet: deps.egressInfo(),\n    probedAt: snapshot.at ?? 0,\n    announcementVersion: ANNOUNCEMENT_VERSION,\n    disclaimerVersion: DISCLAIMER_VERSION,\n    version: deps.meta().version,\n    distribution: deps.meta().distribution,\n    announcements: { unread: feedView.unread, fetchedAt: feedView.fetchedAt },\n    // One bit for the settings page: false with an empty EAC group means the\n    // gate never opened (a host the kernel gave no profile context), which is a\n    // different sentence from \"the relay is down\" (issue #60).\n    laneAvailable: deps.laneAvailable?.() === true,\n    // The last GitHub-authorization verdict (the settings page refreshes it via\n    // /eac/status on mount). `authorized: false` with the lane available is the\n    // one state the model cards badge as locked.\n    eacAuth: deps.eacAuth?.cached?.() ?? null,\n    // Whether the absorbed free-channel pack is live on this host, and its\n    // failure reason when it is not (see the mount in `apply`).\n    channels: deps.channels?.() ?? { state: 'unknown', error: '' },\n    update: { available: update.available, latest: update.latest, current: update.current, checkedAt: update.checkedAt, applying: update.applying, managed: update.managed === true },\n  }\n}\n"
    },
    {
      "path": "src/adapter.js",
      "content": "/**\n * The provider adapter.\n *\n * It satisfies the harness adapter contract structurally — `registerAdapter`\n * validates by calling the methods, not by an `instanceof` test — which is what\n * lets this plugin mount on more than one kernel line without importing a\n * version-pinned adapter base class.\n *\n * Two routes are published from one adapter instance, because the harness groups\n * the model picker strictly by provider route and offers no other grouping\n * field: `our-free-model` carries what this egress can use right now, and\n * `our-free-model-region` carries what the gateway refuses on this egress. A\n * group with no models is dropped from the picker by the client, so a user whose\n * VPN unlocks the region-gated models sees one group, and a user without sees\n * the second group labelled as such.\n *\n * @module src/adapter.js\n */\n\nimport { applyFingerprint, baseModelId, endpointFor, mintRequestId, sessionForConversation, wireFor } from './upstream.js'\nimport { toChatMessages, toClaudeMessages, toResponseInput, toToolDefs, repairToolPairing } from './messages.js'\nimport { CODE, UpstreamError, postStreamed } from './http.js'\nimport { postSealedStreamed } from './eac.js'\nimport { postKiloStreamed } from './kilo.js'\nimport { postAggregateStreamed, isAggregateEntry } from './aggregate.js'\nimport { finishReason, readStream, sanitizeUsage, windowTokens } from './stream.js'\nimport { DEFAULT_LEVEL, MIN_BUDGET, budgetFor, defaultEffortFor, effortPatchFor, effortsFor, hasDeclaredEffortMenu, resolveLevel } from './effort.js'\nimport { createChannel } from './channel.js'\nimport { recoveryPolicy, canRecover, canRecoverSilentStop, recoveryMessages, continuationMessages, checkpointFits, addUsage, createBlockTracker } from './recovery.js'\nimport { isEacEntry, isKiloEntry } from './catalog.js'\nimport { isComboEntry, comboChain } from './combos.js'\nimport { applyTokenSavers, saverConfig } from './token-saver.js'\nimport { classifyFailure, describeVerdict, shouldAdvance } from './route/classify.js'\nimport { FALLBACK_IMAGE_PRICING } from './image-pricing.js'\nimport { isSubscriptionEntry, subscriptionChunks } from './subscription-adapter.js'\n\n/**\n * How long a combo candidate may stay silent before the chain counts the try as\n * failed.\n *\n * `runCombo` commits to a candidate only once an answer-bearing chunk arrives,\n * and a candidate whose upstream accepts the request and then sends nothing —\n * keepalive comments only, no deltas — never settles `iterator.next()`. With no\n * deadline that single await blocks the whole chain, so the fallback that exists\n * for exactly this case never reaches its next link. Availability probes do not\n * cover the shape either: the gateway answers 200, so the probe reads it as up.\n *\n * Only the pre-commit window is bounded. Once an answer delta has been handed\n * over the answer belongs to the caller and the original unbounded await stays,\n * so a slow-but-alive model is never cut off mid-stream — a reasoning model that\n * thinks for a minute while streaming its thoughts keeps resetting the clock.\n */\nconst CHAIN_SILENCE_MS = 25_000\n\n/** Distinguishes \"the watchdog fired\" from a row the iterator really produced. */\nconst SILENT_CANDIDATE = Symbol('ofm-silent-candidate')\n\n/**\n * Await one iterator step, giving up when the candidate stays silent for `ms`.\n * A timeout is reported as an advanceable end-of-try, so `runCombo` walks on\n * exactly as it would after a classified failure.\n */\nasync function nextOrSilence(iterator, ms) {\n  let timer\n  try {\n    const silence = new Promise(resolve => { timer = setTimeout(() => resolve(SILENT_CANDIDATE), ms) })\n    const row = await Promise.race([iterator.next(), silence])\n    if (row !== SILENT_CANDIDATE) return row\n    // Best effort: a pending next() cannot be interrupted, but the generator's\n    // own finally blocks abort its transport once it settles.\n    try { iterator.return?.(undefined) } catch {}\n    return { done: true, value: { advance: true, verdict: null } }\n  } finally {\n    clearTimeout(timer)\n  }\n}\n\nexport const ROUTE_MAIN = 'our-free-model'\nexport const ROUTE_REGION = 'our-free-model-region'\n\n/** Group headings — the only strings the picker shows as a section title. */\nexport const ROUTE_LABELS = {\n  [ROUTE_MAIN]: 'Our Free Model',\n  [ROUTE_REGION]: 'Our Free Model · region-limited',\n}\n\nconst STYLE_FOR_WIRE = { chat: 'chat', responses: 'flat', messages: 'claude' }\n\n// One process-level flag, not per-turn: the first id-less turn that lands on the\n// reserved \"global\" session is what the user needs to hear about, not every\n// title generation or summary that follows it.\nlet globalSessionWarned = false\n\nexport class FreeModelAdapter {\n  /**\n   * @param {object} dependencies\n   * @param {() => {catalog: Array<object>, membership: Record<string, string[]>, settings: object, attributionUserAgent: string}} dependencies.state\n   * @param {(ref: object) => string | undefined} [dependencies.resolveImage]\n   * @param {(record: object) => void} dependencies.recordUsage\n   * @param {(record: object) => void} [dependencies.recordTurn]\n   * @param {(message: string) => void} [dependencies.warn]\n   * @param {{complete: (request: object, onChunk: Function) => Promise<object>}} [dependencies.subscriptionRuntime]\n   */\n  constructor(dependencies) {\n    this.deps = dependencies\n  }\n\n  providerInfo(provider) {\n    return { id: provider, name: ROUTE_LABELS[provider] ?? provider }\n  }\n\n  /**\n   * A fully resolved policy, not a configuration fragment.\n   *\n   * Both the 0.1.5 and 0.1.7 kernels store this object verbatim instead of\n   * running it through their policy resolver, and the backoff scheduler reads the\n   * delay fields off the top level. Reporting them nested under `backoff` makes\n   * every scheduled delay `NaN`, which the durable session log then rejects —\n   * turning a recoverable transient failure into an aborted turn.\n   */\n  providerRetryPolicy() {\n    return Object.freeze({\n      mode: 'normal',\n      maxRetries: 2,\n      // A regional refusal is a property of the egress, not a transient fault;\n      // retrying it only spends quota. It is deliberately absent here. So is\n      // RATE_LIMIT: this lane's 429 carries a *growing* retry-after, and the two\n      // automatic retries turned every quota wall into three walls — the same\n      // turn, paid thrice, arriving later (issue #13).\n      retryableCodes: Object.freeze(['EMPTY_RESPONSE', 'SERVER', 'TIMEOUT', 'TRANSPORT']),\n      initialDelayMs: 700,\n      maxDelayMs: 8000,\n      jitterRatio: 0.2,\n    })\n  }\n\n  /**\n   * Resolve provider-side request-image pricing for one exact model route.\n   *\n   * 宿主 spill-policy 遇到 undefined 会放弃整条含图结果的落盘（issue #151）。\n   * 免费出口没有统一视觉计价协议，提供同步估算以支持预算与落盘。\n   *\n   * Must stay synchronous: the token meter resolves it per measurement, with no\n   * I/O window (issue #42).\n   *\n   * @param {string} _provider - a route passed to `registerAdapter()` for this instance.\n   * @param {string} _model - exact model id passed to GenerateOptions.model.\n   * @returns {typeof FALLBACK_IMAGE_PRICING} 视觉 Token 估算，不是厂商真实消耗。\n   */\n  imageRequestPricing(_provider, _model) {\n    return FALLBACK_IMAGE_PRICING\n  }\n\n  /** Models this route advertises right now. */\n  async listModels(provider) {\n    const state = this.deps.state()\n    const ids = new Set(state.membership[provider] ?? [])\n    return state.catalog\n      .filter(entry => ids.has(entry.id))\n      .map(entry => ({\n        provider,\n        id: entry.id,\n        name: entry.name,\n        description: describe(entry, state.settings),\n        inputModalities: entry.vision ? ['text', 'image'] : ['text'],\n      }))\n  }\n\n  async resolveModel(provider, model) {\n    const state = this.deps.state()\n    const entry = state.catalog.find(candidate => candidate.id === baseModelId(model))\n    if (entry === undefined) {\n      return {\n        provider,\n        id: baseModelId(model),\n        name: baseModelId(model),\n        context: { contextWindow: 131072 },\n        defaultMaxTokens: 8192,\n      }\n    }\n    const ceiling = Math.min(entry.maxOutput, state.settings.defaultMaxTokens ?? 32768)\n    const efforts = effortsFor(entry, undefined, state.settings.defaultMaxTokens)\n    return {\n      provider,\n      id: entry.id,\n      name: entry.name,\n      inputModalities: entry.vision ? ['text', 'image'] : ['text'],\n      context: { contextWindow: entry.contextWindow },\n      defaultMaxTokens: ceiling,\n      ...efforts === undefined ? {} : { reasoning: { efforts, defaultEffort: defaultEffortFor(entry) } },\n    }\n  }\n\n  /**\n   * Bind model metadata and the dispatch closure to one state snapshot, so a\n   * catalog refresh arriving mid-turn cannot mix one generation's capacities\n   * with another's endpoint table.\n   */\n  async prepareCall(provider, model) {\n    const snapshot = this.deps.state()\n    const entry = snapshot.catalog.find(candidate => candidate.id === baseModelId(model)) ?? null\n    return {\n      model: await this.resolveModel(provider, model),\n      stream: options => this.stream(options, entry, snapshot),\n    }\n  }\n\n  /**\n   * @param {object} options - GenerateOptions\n   * @param {object|null} pinned - catalog row frozen by `prepareCall`, if any\n   * @param {object} [snapshot] - state generation frozen by `prepareCall`\n   */\n  stream(options, pinned, snapshot = this.deps.state()) {\n    const controller = new AbortController()\n    const onAbort = () => controller.abort(options.signal?.reason)\n    if (options.signal?.aborted === true) onAbort()\n    else options.signal?.addEventListener('abort', onAbort, { once: true })\n    const iterator = this.runStream({ ...options, signal: controller.signal }, pinned, snapshot)\n    const cleanup = () => options.signal?.removeEventListener('abort', onAbort)\n    const step = async (method, value) => {\n      try {\n        const row = await iterator[method](value)\n        if (row.done) cleanup()\n        return row\n      } catch (error) {\n        cleanup()\n        throw error\n      }\n    }\n    // 原生生成器把 return 排在 pending next 后；先取消请求才能立即退出。\n    return {\n      [Symbol.asyncIterator]() { return this },\n      next: value => step('next', value),\n      return: value => { controller.abort(); cleanup(); return step('return', value) },\n      throw: error => { controller.abort(error); cleanup(); return step('throw', error) },\n    }\n  }\n\n  /**\n   * One turn: a combo walks its chain, everything else is a single model.\n   *\n   * A combo is a virtual model, so it reaches here as a pinned catalog row like\n   * any other; the only difference is that its row carries a chain instead of an\n   * endpoint. Resolving that here — rather than at the picker or the gateway —\n   * means both callers get the failover for free.\n   */\n  async * runStream(options, pinned, snapshot) {\n    const modelId = baseModelId(options.model)\n    const entry = pinned ?? snapshot.catalog.find(candidate => candidate.id === modelId) ?? null\n    if (entry !== null && isComboEntry(entry)) {\n      yield * this.runCombo(options, entry, snapshot)\n      return\n    }\n    yield * this.runSingle(options, entry, snapshot, {})\n  }\n\n  /**\n   * Walk a combo's chain until one candidate produces output.\n   *\n   * The commit rule is the whole design. Chunks are held in a buffer until the\n   * first answer-bearing delta, so a candidate that fails before that point is\n   * discarded whole: the caller never saw a byte of it, and switching models is\n   * invisible. Reasoning deltas are deliberately *not* a commit — \"thought for a\n   * minute, then hit a quota wall\" is the single most valuable case to fail over,\n   * and the held thinking is dropped along with the rest of the discarded try.\n   *\n   * Once an answer delta has been handed over